impl AuditFlusher {
    /// Writes every pending event to the audit sink, then clears the buffer.
    /// Write failures are counted but never block the flush.
    pub fn flush(&mut self) {
        let sink = &self.sink;
        let _ = self.pending.iter().map(|e| { //!issue:1
            if sink.write(e).is_err() {
                metrics::counter!("audit_write_failures").increment(1);
            }
        });
        self.pending.clear();
    }
}

