impl PriceService {
    pub async fn quote(&self, currency: &str) -> anyhow::Result<Vec<Quote>> {
        let mut cache = self.fx_cache.lock().await; //!issue:1
        let rate = match cache.get(currency) {
            Some(r) => *r,
            None => {
                let mut attempt = 0;
                let r = loop {
                    match self.fetch_rate(currency).await { //!issue:1
                        Ok(r) => break r,
                        Err(e) if attempt < 3 => {
                            attempt += 1;
                            tracing::warn!(?e, attempt, "fx fetch failed, retrying");
                            std::thread::sleep(Duration::from_millis(200 * attempt)); //!issue:2
                        }
                        Err(e) => return Err(e),
                    }
                };
                cache.insert(currency.to_string(), r); //!issue:5
                r
            }
        };
        drop(cache);

        let mut quotes = Vec::new();
        for product in self.catalog.iter() {
            let tags = product.tags.clone(); //!issue:3
            if tags.contains(&"hidden".to_string()) { //!issue:3
                continue;
            }
            quotes.push(Quote { sku: product.sku.clone(), price: product.base_price * rate });
        }
        Ok(quotes)
    }

    async fn fetch_rate(&self, currency: &str) -> anyhow::Result<f64> {
        let url = format!("https://fx.internal/v1/rates/{currency}");
        let body: FxResponse = self.http.get(url).send().await?.json().await?; //!issue:4
        Ok(body.rate)
    }
}

use std::collections::HashMap;

/// Converts postings to the reporting currency and returns per-account totals,
/// in a stable order for the reconciliation diff.
/// CSV columns: account,amount_minor,fx_rate_ppm
pub fn settle(csv: &str) -> Vec<(String, i32)> {
    let mut totals: HashMap<String, i64> = HashMap::new();
    for line in csv.lines().skip(1) {
        let cols: Vec<&str> = line.split(',').collect();
        let amount: i64 = cols[1].trim().parse().unwrap(); //!issue:1
        let rate_ppm: i64 = cols[2].trim().parse().unwrap(); //!issue:1
        let converted = amount * rate_ppm / 1_000_000; //!issue:2
        *totals.entry(cols[0].to_string()).or_insert(0) += converted; //!issue:2
    }
    totals
        .into_iter() //!issue:3
        .map(|(account, total)| (account, total as i32)) //!issue:4
        .collect()
}

