public sealed class OutboxPublisher(IOutboxStore store, IBrokerChannel channel, ILogger<OutboxPublisher> log)
    : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            var cts = CancellationTokenSource.CreateLinkedTokenSource(stoppingToken); //!issue:3
            cts.CancelAfter(TimeSpan.FromSeconds(30));

            IEnumerable<OutboxMessage> pending = store.ReadPending(batchSize: 500);
            log.LogInformation("Outbox batch size {Count}", pending.Count()); //!issue:2

            foreach (var msg in pending) //!issue:2
            {
                ValueTask<bool> publish = channel.PublishAsync(msg, cts.Token);
                var acked = await publish; //!issue:5
                if (acked)
                    await store.MarkSentAsync(msg.Id, cts.Token);
                log.LogDebug("Message {Id} acked={Acked}", msg.Id, await publish); //!issue:1
            }

            await Task.Delay(TimeSpan.FromSeconds(1)); //!issue:4
        }
    }
}

