    public ArchiveUploader(BlobClient client) {
        this.client = client;
    }

    public List<Receipt> uploadAll(List<Path> files) {
        List<CompletableFuture<Receipt>> futures = files.stream()
                .map(f -> CompletableFuture.supplyAsync(() -> uploadUnchecked(f))) //!issue:1
                .toList();
        return futures.stream().map(CompletableFuture::join).toList(); //!issue:4
    }

    private Receipt uploadUnchecked(Path file) {
        try {
            return upload(file);
        } catch (IOException e) {
            throw new IllegalStateException("upload failed: " + e.getMessage()); //!issue:3
        }
    }

    private Receipt upload(Path file) throws IOException {
        BlobOutputStream out = client.openUpload(file.getFileName().toString());
        try {
            Files.copy(file, out);
        } finally {
            out.close(); //!issue:2
        }
        return out.receipt();
    }
}
